const result = $input.first().json;
if (result.allSynthetic !== true || !result.candidate?.id || !Array.isArray(result.top3)) {
  throw new Error('Expected a synthetic candidate-to-jobs shortlist from the matching engine.');
}
if (result.top3.length === 0) {
  throw new Error('No jobs to store. Main workflow should handle empty shortlist before invoking persistence.');
}
return result.top3.map(job => ({ json: {
  recordKey: `${result.candidate.id}::${job.id}`,
  candidateId: String(result.candidate.id),
  jobId: String(job.id),
  candidateName: String(result.candidate.name || ''),
  jobTitle: String(job.title || ''),
  company: String(job.company || ''),
  score: Number(job.score || 0),
  reason: String(job.reason || ''),
  lastChecked: new Date().toISOString()
}}));

// Passes the ranked jobs back to the caller, plus what Postgres returned:
// how many rows were upserted and how often / since when this candidate's matches were saved.
const original = $('Called with Ranked Jobs').first().json;
const rows = $input.all().map(i => i.json);
const firstSaved = rows.map(r => new Date(r.first_saved)).sort((a, b) => a - b)[0];
return [{ json: { ...original, persistedRows: rows.length, storage: 'Postgres bait_recommendations',
  timesSaved: Math.max(...rows.map(r => Number(r.times_saved) || 1)),
  firstSaved: firstSaved ? firstSaved.toISOString() : null } }];
